			IntStream.range(0, n).forEach(i -> paths[i] = new HashSet<>());
			IntStream.range(0, m).forEach(i -> {
				int a = scanner.nextInt() - 1;
				int b = scanner.nextInt() - 1;
				paths[a].add(b);
				paths[b].add(a);
			});
