	public static void main(String[] args) throws IOException {

		// input
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		String numString = "";
		for (int i = 2; i <= n; i++) {
			numString = numString + i;
		}
		int m = in.nextInt();
		int[][] mat = new int[n + 1][n + 1];
		for (int i = 0; i < m; i++) {
			int ai = in.nextInt();
			int bi = in.nextInt();
			mat[ai][bi] = 1;
			mat[bi][ai] = 1;
		}

