        int currentWeight = 0;
        for (int w : packages) {
            if (currentWeight + w <= maxLoad) {
                currentWeight += w;
            } else {
                k--;
                currentWeight = w;
            }

            if (k == 0) {
                return false;
            }
        }
        return true;
    }

    private static int binarySearch(int left, int right, int k, int[] packages) {
        int mid = (left + right) / 2;
