import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.util.stream.Collectors;

public class Main {

	public static void main(String args[]) {
		ConsoleScanner cin = new ConsoleScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	static long now() {
		return System.currentTimeMillis();
	}

	static void trace(Object... objects) {
		assert null != System.out.format("trace:%s\n", Arrays.deepToString(objects));
	}

	private static void solve(ConsoleScanner cin, PrintWriter cout) {
		// assert solve(1) == 1;

		int n = cin.nextInt();
		long[] t = new long[n];
		for (int i = 0; i < t.length; i++)
			t[i] = cin.nextLong();

		long start = now();

		long ans = solve(n, t);

		cout.println(ans);
		trace("elapsed", now() - start);
	}

	private static long solve(int n, long[] t) {
		ArrayDeque<Long> deq = new ArrayDeque<>();
		deq.addAll(Arrays.stream(t).boxed().collect(Collectors.toList()));
		while (deq.size() >= 2) {
			long a = deq.poll();
			long b = deq.poll();
			long gcd = gcd(a, b);
			long lcm = a / gcd * b;
			deq.add(lcm);
		}
		long ans = deq.poll();
		return ans;
